import json, sys, itertools
T = "tests/acceptance/X/zz.py"
P = ["echo ${v%% #*}", "echo ${v:- #'}", "echo \"${v:- #}\"", "echo ${v:-\"#\"}", "grep -c b <<< \"a # b\"",
     "grep x <<< y # it's", "cat <<< \"x\" # c", "wc -l <<< 'a # b'", "echo ${#v}", "echo $# # x",
     "bash <<< \"a # b\"", "cat <<< x | sh", "x=${v:-<<EOF}", "echo ${v/#/x}", "echo ${v:-$(echo a # c\n)}",
     "echo ${v:-`echo a # c`}", "echo $${v", "echo '${' # c", "echo \"${v:-it's}\"", "echo ${v:-'#'}",
     "echo ${v:- # \"}", "tr a b <<< \"$v\" # don't", "echo ${v:-}}", "echo ${v:-{}", "cat <<<EOF",
     "sort <<< \"${v%% #*}\"", "echo ${v%%'}'#*}", "echo x\\ #y", "echo ${v:-\\}} # '", "python3 <<< \"a # b\""]
S = ["; ", " && ", "\n", " | ", " # ", " #'", " ", "\n# it's\n"]
W = [f"touch {T}", f"echo x > {T}", "gov pause --off", f"bash -c 'touch {T}'", f"echo $(touch {T})",
     f"cp /dev/null {T}", f"python3 -c \"open('{T}','w')\"", f"cat <<'X9'\nq\nX9\ntouch {T}"]
X = ["", " # it's", " # \"", " ${v%% #*}", " '"]


def wrap(c, k):
    if k == 0:
        return c
    if k == 1:
        return f"bash <<'EOF'\n{c}\nEOF"
    if k == 2:
        return f"bash <<EOF\n{c}\nEOF"
    if k == 3:
        return f"y=$( {c}\n)"
    if k == 4:
        return f"{{ {c}\n}}"
    if k == 5:
        return f"cat <<'EOF' | sh\n{c}\nEOF"


out = set()
for p, s, w, x in itertools.product(P, S, W, X):
    for c in (p + s + w + x, w + s + p + x):
        for k in range(6):
            out.add(wrap(c, k))
out = sorted(out)
json.dump(out, open(sys.argv[1], "w"))
print(len(out))
